import { useState } from "react";
import { useNavigate } from "react-router-dom";

export default function Login() {
  const [form, setForm] = useState({ username: "", password: "" });
  const navigate = useNavigate();

  const login = async (e) => {
    e.preventDefault();

    const res = await fetch("http://localhost:5001/admin/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form),
    });

    const data = await res.json();

    if (data.token) {
      localStorage.setItem("adminToken", data.token);
      navigate("/admin/dashboard");
    }
  };

  return (
    <div className="min-h-screen bg-black flex items-center justify-center">
      <form
        onSubmit={login}
        className="bg-black border border-white/10 p-10 rounded-2xl w-full max-w-md"
      >
        <h2 className="text-3xl font-bold text-[#e9b21a] mb-8 text-center">
          Admin Login
        </h2>

        <input
          placeholder="Username"
          className="w-full mb-4 px-4 py-3 rounded bg-black border border-white/20"
          onChange={(e) =>
            setForm({ ...form, username: e.target.value })
          }
        />

        <input
          type="password"
          placeholder="Password"
          className="w-full mb-6 px-4 py-3 rounded bg-black border border-white/20"
          onChange={(e) =>
            setForm({ ...form, password: e.target.value })
          }
        />

        <button className="w-full py-3 rounded-full bg-[#e9b21a] text-black font-semibold">
          Login
        </button>
      </form>
    </div>
  );
}
